function setVisualState(id){
  NODES.forEach(function(n){
    var g = document.getElementById('node-'+n.id);
    var link = document.querySelector('[data-link="'+n.id+'"]');
    g.classList.remove('active','dim');
    link.classList.remove('dim');
    if (id && id !== 'context'){
      if (n.id === id) g.classList.add('active');
      else { g.classList.add('dim'); link.classList.add('dim'); }
    }
  });
  var ring = document.getElementById('ring');
  var ringLabel = document.getElementById('ringLabel');
  ring.classList.remove('active','dim');
  ringLabel.classList.remove('active');
  if (id === 'context'){ ring.classList.add('active'); ringLabel.classList.add('active'); }
  else if (id){ ring.classList.add('dim'); }
}

