def hub_svg():
    import math
    CX, CY, R = 450, 380, 230
    links = []
    nodes = []
    for m in HUB_META:
        rad = math.radians(m["angle"])
        x = CX + R*math.sin(rad)
        y = CY - R*math.cos(rad)
        links.append('<line x1="%d" y1="%d" x2="%.1f" y2="%.1f" class="link" data-link="%s"/>' % (CX,CY,x,y,m["id"]))
        gap = node_pages[m["id"]]["gap"]
        nodes.append(
          '<g class="node" id="node-%s" tabindex="0" role="button" aria-label="%s：%s">'
          '<rect x="%.1f" y="%.1f" width="190" height="76" rx="14"/>'
          '<text x="%.1f" y="%.1f" text-anchor="middle" font-weight="700" font-size="21">%s</text>'
          '<text x="%.1f" y="%.1f" class="gap" text-anchor="middle" font-size="14">%s</text>'
          '</g>' % (m["id"], m["label"], gap, x-95, y-38, x, y-8, m["label"], x, y+18, gap)
        )
    ring = '<circle id="ring" class="ring" cx="%d" cy="%d" r="330"/><circle id="ringHit" class="ring-hit" cx="%d" cy="%d" r="330"/>' % (CX,CY,CX,CY)
    ring_label = '<text id="ringLabel" class="ring-label" x="%d" y="40" text-anchor="middle">%s</text><text class="mono-note" x="%d" y="60" text-anchor="middle">快取 caching · 清除 editing · 壓縮 compaction</text>' % (CX, node_pages["context"]["label"], CX)
    center = ('<g class="node center-box" id="node-core" tabindex="0" role="button" aria-label="核心：hermes-agent 的 Model Tools Loop 迴圈">'
      '<rect x="360" y="332" width="180" height="96" rx="16"/>'
      '<text x="450" y="372" text-anchor="middle" font-weight="700" font-size="22">hermes-agent</text>'
      '<text x="450" y="396" class="gap" text-anchor="middle" font-size="14">MODEL · TOOLS · LOOP</text>'
      '</g>')
    return ('<svg id="map" viewBox="0 0 900 760" role="img" aria-label="hermes-agent 心智圖：中心是核心迴圈，六個節點環繞四周，一個貫穿六者的虛線環代表 Context 維護">'
      + ''.join(links) + ring + ring_label + center + ''.join(nodes) + '</svg>')

