      var tcid = SLIDE_CLUSTER[target];
      var tag = document.createElement('span');
      tag.className = 'tag';
      tag.textContent = '→ ' + clusterById[tcid].label;
      btn.appendChild(tag);
      btn.addEventListener('click', function(){ openSlide(target); });
      linksWrap.appendChild(btn);
    });
  }

  var pIdx = PLAY_ORDER.indexOf(slideId);
  $('progressLabel').textContent = (pIdx+1) + ' / ' + PLAY_ORDER.length;
  $('progressBar').style.width = ((pIdx+1)/PLAY_ORDER.length*100) + '%%';
  $('navMid').textContent = c.label + ' · ' + (idx+1) + '/' + list.length;
  $('prevBtn').disabled = pIdx <= 0;
  $('nextBtn').disabled = pIdx >= PLAY_ORDER.length - 1;

  $('overview').classList.remove('active');
  $('slide').classList.add('active');
  window.scrollTo(0,0);
  $('slide').dataset.current = slideId;
}

function closeSlide(){
  $('slide').classList.remove('active');
  $('overview').classList.add('active');
  window.scrollTo(0,0);
}

function stepPlay(delta){
  var cur = $('slide').dataset.current;
  var i = PLAY_ORDER.indexOf(cur);
  var next = i + delta;
  if (next < 0 || next >= PLAY_ORDER.length) return;
  openSlide(PLAY_ORDER[next]);
}

CLUSTER_ORDER.forEach(function(cid){
  var g = cid === 'core' ? $('node-core') : $('node-'+cid);
  if (!g) return;
  g.addEventListener('click', function(){ openSlide(SLIDES[cid][0].id); });
  g.addEventListener('keydown', function(ev){ if(ev.key==='Enter'||ev.key===' '){ ev.preventDefault(); openSlide(SLIDES[cid][0].id); } });
