def outline_html():
    parts = []
    for i, c in enumerate(CLUSTERS, 1):
        subs = ''.join(
          '<li><button data-jump="%s"><span class="n">%d.%d</span>%s</button></li>' % (s['id'], i, j+1, s['title'])
          for j, s in enumerate(SLIDES[c['id']])
        )
        parts.append(
          '<li class="outline-sec">'
          '<button class="outline-sec-head" data-jump="%s"><span class="secnum">%d</span>'
          '<span class="sectitle">%s</span><span class="secgap">%s</span></button>'
          '<ul class="outline-sub">%s</ul>'
          '</li>' % (SLIDES[c['id']][0]['id'], i, c['label'], c['gap'], subs)
        )
    return '<ol class="outline-list">' + ''.join(parts) + '</ol>'

def drawer_html():
    parts = []
    for c in CLUSTERS:
        items = ''.join(
          '<li><button data-jump="%s" data-slide="%s">%s</button></li>' % (s['id'], s['id'], s['title'])
          for s in SLIDES[c['id']]
        )
        parts.append('<div class="drawer-sec"><div class="drawer-sec-title">%s</div><ul>%s</ul></div>' % (c['label'], items))
    return ''.join(parts)

