import re, json
path = "/Users/kurtshen/Desktop/Harness 心智圖＋課程.html"
data = open(path, encoding='utf-8').read()
m2 = re.search(r'var SLIDES = (\{.*?\});\s*var CLUSTERS', data, re.S)
slides = json.loads(m2.group(1))

def text_width(t, size):
    w=0.0
    for ch in t:
        w += size*(1.0 if ord(ch)>0x2E80 else 0.55)
    return w

oob=0
for cid, arr in slides.items():
    for s in arr:
        d = s.get('diagram','')
        if not d: continue
        vb_m = re.search(r'viewBox="([\d\. ]+)"', d)
        _,_,W,H = [float(x) for x in vb_m.group(1).split()]
        for tag, attrs in re.findall(r'<(rect|text)\s+([^>]*)/?>', d):
            xs = re.findall(r'\bx="(-?[\d\.]+)"', attrs)
            ys = re.findall(r'\by="(-?[\d\.]+)"', attrs)
            for x in xs:
                if float(x) < 0 or float(x) > W: oob+=1; print("OOB x",cid,s['id'],x,W)
            for y in ys:
                if float(y) < 0 or float(y) > H: oob+=1; print("OOB y",cid,s['id'],y,H)
print("out-of-bounds:", oob)

overflow=0
for cid, arr in slides.items():
    for s in arr:
        d = s.get('diagram','')
        if not d: continue
        for rm in re.finditer(r'<rect class="dg-box[^"]*" x="(-?[\d.]+)" y="(-?[\d.]+)" width="([\d.]+)" height="([\d.]+)"', d):
            rx,ry,rw,rh = map(float, rm.groups())
            rest = d[rm.end():rm.end()+400]
            tm = re.search(r'<text class="dg-text"[^>]*font-size="(\d+)"[^>]*>([^<]*)</text>', rest)
            if not tm: continue
            fsize,label = tm.groups(); fsize=float(fsize)
            w = text_width(label, fsize)
            if w > rw*0.95: overflow+=1; print("OVERFLOW",cid,s['id'],label,round(w,1),rw)
            subm = re.search(r'<text class="dg-mono"[^>]*font-size="(\d+)"[^>]*>([^<]*)</text>', rest[:100])
            if subm:
                fsize2,sub = subm.groups(); fsize2=float(fsize2)
                w2 = text_width(sub, fsize2)
                if w2 > rw*0.95: overflow+=1; print("OVERFLOW(sub)",cid,s['id'],sub,round(w2,1),rw)
print("text overflow:", overflow)
print("total slides:", sum(len(v) for v in slides.values()))
EOF

