import re, json
path = "/Users/kurtshen/Desktop/Harness 心智圖＋課程.html"
data = open(path, encoding='utf-8').read()
m = re.search(r'<script>([\s\S]*?)</script>', data)
open('/tmp/extracted_scriptP.js','w',encoding='utf-8').write(m.group(1))
print("svg:", data.count('<svg'), data.count('</svg>'))
print("div:", data.count('<div'), data.count('</div>'))

m2 = re.search(r'var SLIDES = (\{.*?\});\s*var CLUSTERS', data, re.S)
slides = json.loads(m2.group(1))
print("total slides:", sum(len(v) for v in slides.values()))
for cid, arr in slides.items():
    print(cid, [s['id'] for s in arr])

bad=0; refs=0; oob=0
def text_width(t, size):
    w=0.0
    for ch in t:
        w += size*(1.0 if ord(ch)>0x2E80 else 0.55)
    return w
overflow=0
for cid, arr in slides.items():
    for s in arr:
        d = s.get('diagram','')
        if not d: continue
        marker_ids = set(re.findall(r'<marker id="([^"]+)"', d))
        used = re.findall(r'marker-end="url\(#([^"]+)\)"', d)
        for u in used:
            refs+=1
            if u not in marker_ids: bad+=1; print("BROKEN ARROW", cid, s['id'])
        vb_m = re.search(r'viewBox="([\d\. ]+)"', d)
        _,_,W,H = [float(x) for x in vb_m.group(1).split()]
        for tag, attrs in re.findall(r'<(rect|text)\s+([^>]*)/?>', d):
            for x in re.findall(r'\bx="(-?[\d\.]+)"', attrs):
                if float(x)<0 or float(x)>W: oob+=1; print("OOB", cid, s['id'])
            for y in re.findall(r'\by="(-?[\d\.]+)"', attrs):
                if float(y)<0 or float(y)>H: oob+=1; print("OOB", cid, s['id'])
        for rm in re.finditer(r'<rect class="dg-box[^"]*" x="(-?[\d.]+)" y="(-?[\d.]+)" width="([\d.]+)" height="([\d.]+)"', d):
            rw = float(rm.group(3))
            rest = d[rm.end():rm.end()+400]
            tm = re.search(r'<text class="dg-text"[^>]*font-size="(\d+)"[^>]*>([^<]*)</text>', rest)
            if tm:
                w=text_width(tm.group(2),float(tm.group(1)))
                if w > rw*0.95: overflow+=1; print("OVERFLOW",cid,s['id'],tm.group(2))
            subm = re.search(r'<text class="dg-mono"[^>]*font-size="(\d+)"[^>]*>([^<]*)</text>', rest[:100])
            if subm:
                w2=text_width(subm.group(2),float(subm.group(1)))
                if w2 > rw*0.95: overflow+=1; print("OVERFLOW(sub)",cid,s['id'],subm.group(2))
print("arrows:", refs, "broken:", bad, "| oob:", oob, "| overflow:", overflow)
EOF
